package org.eclipse.kura.internal.rest.auth.jwt;

import java.util.Map;

import org.junit.Test;

import jakarta.ws.rs.core.Response.Status;

public class RefreshTokenFamilyOwnershipTest extends AbstractRefreshTokenFamilyScenario {

    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();
    private static final String OTHER_IDENTITY = "bob";

    private String ownerRefreshToken;
    private String foreignRefreshToken;

    @Test
    public void aRefreshTokenOfAnotherIdentityRevokesTheFamily() {
        givenTheIdentityExists(OTHER_IDENTITY);
        givenTheOwnerLoggedIn();
        givenARefreshTokenIssuedTo(OTHER_IDENTITY, inTheFamilyOf(this.ownerRefreshToken));
        givenTheRefreshTokenWasExchanged(this.foreignRefreshToken);

        whenTheRefreshTokenIsExchanged(this.ownerRefreshToken);

        thenTheExchangeStatusesAre(UNAUTHORIZED, UNAUTHORIZED);
    }

    private void givenTheIdentityExists(final String identityName) {
        createIdentity(identityName);
    }

    private void givenTheOwnerLoggedIn() {
        this.ownerRefreshToken = login().refreshToken();
    }

    private void givenARefreshTokenIssuedTo(final String identityName, final Map<String, Object> familyClaims) {
        this.foreignRefreshToken = externalRefreshTokenWith(identityName, familyClaims);
    }

    private void givenTheRefreshTokenWasExchanged(final String refreshToken) {
        exchange(refreshToken);
    }

    private void whenTheRefreshTokenIsExchanged(final String refreshToken) {
        exchange(refreshToken);
    }

    private Map<String, Object> inTheFamilyOf(final String refreshToken) {
        return claimsOf(refreshToken);
    }
}
